window.QUESTION_POOLS = window.QUESTION_POOLS || {};
window.QUESTION_POOLS['aplus2'] = [
  { q: 'Which command verifies the integrity of Windows system files and replaces corrupted ones?', opts: ['chkdsk /r', 'sfc /scannow', 'DISM /Online /Cleanup-Image /RestoreHealth', 'bootrec /fixboot'], answer: 1, exp: 'sfc /scannow (System File Checker) scans protected Windows files and replaces corrupted ones from a cached copy. Run DISM first if sfc reports it cannot fix files.', domain: 'D1' },
  { q: 'You need to encrypt an entire drive on a Windows 10 Pro laptop. What built-in tool should you use?', opts: ['EFS', 'BitLocker', 'VeraCrypt', 'NTFS compression'], answer: 1, exp: 'BitLocker provides full-drive encryption and is built into Windows Pro and Enterprise. EFS encrypts individual files but not the whole drive. BitLocker requires TPM or USB startup key.', domain: 'D2' },
  { q: 'A hard drive makes a clicking noise and the PC cannot boot. What should be the FIRST action?', opts: ['Run chkdsk /r', 'Attempt data recovery immediately — drive is failing', 'Update disk drivers', 'Format and reinstall Windows'], answer: 1, exp: 'Clicking indicates mechanical failure (read/write head crashing). Data recovery must happen immediately before the drive fails completely. Do NOT run chkdsk as it may write to the dying drive.', domain: 'D3' },
  { q: 'Which Windows boot option disables all non-essential drivers and services but includes network access?', opts: ['Safe Mode', 'Safe Mode with Networking', 'Safe Mode with Command Prompt', 'Last Known Good Configuration'], answer: 1, exp: 'Safe Mode with Networking loads minimal drivers AND network support. Use this when you need to download drivers or tools to fix the system. Plain Safe Mode has no network access.', domain: 'D1' },
  { q: 'What is the primary purpose of the TPM chip?', opts: ['Increase graphics performance', 'Store cryptographic keys and enable platform integrity measurement', 'Manage RAM allocation', 'Accelerate network encryption'], answer: 1, exp: 'TPM (Trusted Platform Module) is a secure hardware chip for storing encryption keys, enabling BitLocker, supporting Secure Boot attestation, and providing hardware-based platform integrity verification.', domain: 'D1' },
  { q: 'Which file system is required for full NTFS permissions, encryption, and compression on Windows?', opts: ['FAT32', 'exFAT', 'NTFS', 'ext4'], answer: 2, exp: 'NTFS supports file/folder permissions, EFS encryption, compression, shadow copies, and auditing. FAT32 has no security features. exFAT is cross-platform but no permissions. ext4 is Linux.', domain: 'D1' },
  { q: 'Which backup strategy requires the most time to restore but uses the least daily storage?', opts: ['Full backup daily', 'Differential backup', 'Incremental backup', 'Mirror backup'], answer: 2, exp: 'Incremental backups are smallest (only changes since last backup) but restoration requires the full backup PLUS every incremental since then — the longest restore process.', domain: 'D1' },
  { q: 'Which Linux command displays and sets file permissions using octal notation?', opts: ['chown', 'chgrp', 'chmod', 'ls -l'], answer: 2, exp: 'chmod (change mode) sets permissions: chmod 755 = owner rwx(7), group r-x(5), others r-x(5). ls -l shows current permissions. chown changes ownership.', domain: 'D1' },
  { q: 'Which Windows feature allows you to automatically revert system files and registry to a previous state without affecting user files?', opts: ['Windows Backup', 'System Restore (restore point)', 'WinRE', 'Reset this PC'], answer: 1, exp: 'System Restore reverts system files, registry, and installed programs to a restore point. It does NOT affect personal files. Different from Reset This PC (which reinstalls Windows).', domain: 'D1' },
  { q: 'Which malware type spreads across networks autonomously without requiring a host file or user action?', opts: ['Virus', 'Worm', 'Trojan', 'Ransomware'], answer: 1, exp: 'Worms self-replicate and spread across networks without user interaction or a host file. Viruses require a host file and user execution. Trojans disguise themselves as legitimate software.', domain: 'D2' },
  { q: 'Which event IDs in Windows Security log indicate failed login attempts?', opts: ['4624', '4625', '7036', '4720'], answer: 1, exp: 'Event ID 4625 = failed logon attempt. 4624 = successful logon. 4720 = new account created. 7036 = service state change. Monitor 4625 for brute-force attacks.', domain: 'D1' },
  { q: 'What should be the FIRST step in the CompTIA A+ malware removal procedure?', opts: ['Run antivirus in Safe Mode', 'Quarantine/isolate the infected system', 'Disable System Restore', 'Back up user data'], answer: 1, exp: 'Step 1 is quarantine — isolate the infected system from the network to prevent spread. Then disable System Restore (step 3), then remediate. Isolation prevents the malware from spreading to other systems.', domain: 'D2' },
  { q: 'Which display technology offers the best color accuracy and widest viewing angles for graphic design work?', opts: ['TN panel', 'VA panel', 'IPS panel', 'OLED'], answer: 2, exp: 'IPS (In-Plane Switching) panels provide the most accurate color reproduction and widest viewing angles, making them ideal for graphic design, photo editing, and color-critical work.', domain: 'D1' },
  { q: 'What is the primary security risk of BYOD policies without MDM?', opts: ['Increased licensing costs', 'Unmanaged devices with corporate data and no enforcement of security policies', 'Incompatible apps', 'Bandwidth congestion'], answer: 1, exp: 'Without MDM, BYOD devices may lack encryption, weak PINs, outdated OS, or have corporate data accessible after employment ends. MDM enforces policies, enables remote wipe, and separates corporate/personal data.', domain: 'D1' },
  { q: 'A workstation cannot connect to the internet but CAN ping the default gateway successfully. What is the next troubleshooting step?', opts: ['Replace the NIC', 'Check DNS resolution with nslookup and ping 8.8.8.8', 'Reinstall Windows', 'Check DHCP settings'], answer: 1, exp: 'If pinging the gateway works, LAN connectivity is fine. Next: ping 8.8.8.8 (bypasses DNS — tests routing). If that works but websites fail, DNS is broken. Use nslookup to test name resolution.', domain: 'D1' },
  { q: 'Which tool should a technician use to determine if a memory module is causing system instability?', opts: ['chkdsk', 'sfc /scannow', 'memtest86', 'DISM'], answer: 2, exp: 'memtest86 runs independently of the OS and systematically tests RAM for errors. Run for at least one full pass (preferably multiple). Failing RAM causes BSODs, random restarts, and data corruption.', domain: 'D3' },
  { q: 'What type of fire extinguisher should be used on an electrical equipment fire?', opts: ['Class A (water)', 'Class B (CO2)', 'Class C (non-conductive agent)', 'Class D (dry powder)'], answer: 2, exp: 'Class C extinguishers use non-conductive agents (CO2 or dry chemical) safe for electrical fires. Using water (Class A) on electrical fires creates electrocution risk. ABC extinguishers cover all three types.', domain: 'D1' },
  { q: 'What is the correct command sequence for repairing corrupted Windows system files when the component store is damaged?', opts: ['sfc /scannow then DISM /RestoreHealth', 'DISM /RestoreHealth first, then sfc /scannow', 'chkdsk /r then sfc /scannow', 'bootrec /fixboot then sfc /scannow'], answer: 1, exp: 'Run DISM /Online /Cleanup-Image /RestoreHealth first to repair the component store that sfc relies on. Then run sfc /scannow. Reversed order fails if the component store itself is corrupted.', domain: 'D1' },
  { q: 'Which backup type provides the FASTEST restore but uses the MOST storage space daily?', opts: ['Incremental', 'Differential', 'Full daily backup', 'Synthetic full'], answer: 2, exp: 'A full backup every day gives the fastest single-step restore but uses maximum storage. Incremental is smallest daily but slowest restore. Differential is moderate on both.', domain: 'D1' },
  { q: 'What is the first action when a Windows PC shows a BSOD on every startup after a driver update?', opts: ['Reinstall Windows from scratch', 'Boot to Safe Mode and roll back or uninstall the driver', 'Run memtest86', 'Reset BIOS settings'], answer: 1, exp: 'Safe Mode loads minimal drivers, bypassing the problematic driver. Roll back or uninstall the driver that caused the issue. If Safe Mode is inaccessible, use System Restore from Windows Recovery Environment.', domain: 'D3' },
  { q: 'A user can ping 8.8.8.8 successfully but cannot load any websites by name. What is the problem?', opts: ['Default gateway is wrong', 'DNS resolution is failing', 'NIC driver needs updating', 'Firewall is blocking HTTP'], answer: 1, exp: 'If IP-based connectivity works (pinging 8.8.8.8) but hostname resolution fails, DNS is broken. Check: ipconfig /all (correct DNS server?), ipconfig /flushdns, nslookup to test resolution.', domain: 'D2' },
  { q: 'Which Windows utility allows you to see all active TCP connections and the processes using them?', opts: ['ipconfig /all', 'netstat -an', 'tracert', 'arp -a'], answer: 1, exp: 'netstat -an shows all active connections with port numbers. netstat -b (admin) shows process names. ss is the Linux equivalent. Use to identify which process is listening on a port or making unexpected connections.', domain: 'D1' },
  { q: 'What Windows feature should be DISABLED before attempting malware removal to prevent malware from hiding in restore points?', opts: ['Windows Defender', 'Remote Desktop', 'System Restore', 'Windows Update'], answer: 2, exp: 'Step 3 of the A+ malware removal process: disable System Restore. Malware can hide within restore points and reinfect the system when System Restore is used. Re-enable and create a fresh restore point after cleanup.', domain: 'D2' },
  { q: 'A technician needs to access a Windows PC remotely with a graphical interface. The PC is on the corporate network and runs Windows 10 Pro. What built-in tool is used?', opts: ['SSH', 'Telnet', 'RDP (mstsc.exe, port 3389)', 'VNC'], answer: 2, exp: 'RDP (Remote Desktop Protocol) is built into Windows Pro/Enterprise. Access with mstsc.exe. Requires Remote Desktop to be enabled (System Properties > Remote). Use VPN + RDP rather than exposing port 3389 to the internet.', domain: 'D1' },
  { q: 'Which NTFS permission should be applied to prevent a user from deleting a file while still allowing them to modify its contents?', opts: ['Read and Execute', 'Modify', 'Write only (without Delete sub-permission)', 'Full Control'], answer: 2, exp: 'The Modify permission includes Read, Write, and Delete. To allow editing but prevent deletion, use special permissions and remove the Delete permission specifically. Full Control includes all permissions including deleting.', domain: 'D1' },
  { q: 'Which environmental condition in a server room increases the risk of electrostatic discharge (ESD) damage to components?', opts: ['High humidity (>60%)', 'High temperature (>80F)', 'Low humidity (<40%)', 'High air pressure'], answer: 2, exp: 'Low humidity allows static electricity to build up more easily, increasing ESD risk. Ideal data center humidity: 40-60%. ESD discharge can instantly destroy RAM, CPUs, and motherboards. Use wrist straps and antistatic mats.', domain: 'D4' },
  { q: 'Which cloud deployment model uses a mix of on-premises infrastructure and public cloud services?', opts: ['Public cloud', 'Private cloud', 'Hybrid cloud', 'Community cloud'], answer: 2, exp: 'Hybrid cloud combines on-premises (private) infrastructure with public cloud services, connected via VPN or private link. Most common enterprise approach: keep sensitive data on-prem while using cloud for scalability.', domain: 'D1' },
  { q: 'Regarding the Windows Registry, which hive contains system-wide hardware configuration and service settings?', opts: ['HKCU', 'HKLM', 'HKCR', 'HKU'], answer: 1, exp: 'HKLM (HKEY_LOCAL_MACHINE) contains system-wide settings: hardware, drivers, installed software, and services. HKCU (HKEY_CURRENT_USER) stores the current user\'s settings and preferences.', domain: 'D1' },
  { q: 'A technician needs to determine which startup programs are slowing down Windows boot. Where should they look?', opts: ['Services.msc', 'Task Manager > Startup tab', 'Event Viewer > System', 'Device Manager'], answer: 1, exp: 'Task Manager > Startup tab shows all startup programs, their publisher, and their performance impact (High/Medium/Low/None). Disable unnecessary startup items here. Also available in msconfig > Startup (older Windows).', domain: 'D1' },
  { q: 'What tool should be used to test a network cable for wire mapping and continuity faults?', opts: ['TDR (Time Domain Reflectometer)', 'Cable certifier', 'Basic cable tester', 'Multimeter'], answer: 2, exp: 'A basic cable tester checks continuity and wire mapping (correct pin-to-pin connections at both ends). A TDR locates faults by distance. A certifier performs full IEEE testing. For basic troubleshooting, a simple cable tester suffices.', domain: 'D1' },
  { q: 'When should a technician use a wrist strap when working on computer components?', opts: ['Only when working near high-voltage components like PSUs', 'Whenever handling sensitive electronics to prevent ESD damage', 'Only in data centers with special flooring', 'Only when working with CPUs'], answer: 1, exp: 'Antistatic wrist straps should be used whenever handling electronic components: RAM, CPUs, GPUs, motherboards, expansion cards. ESD (Electrostatic Discharge) can invisibly damage components even with voltages too low to feel.', domain: 'D4' },
  { q: 'What does a Windows Event ID 4625 indicate?', opts: ['Successful user logon', 'Failed logon attempt', 'Account lockout', 'Service started'], answer: 1, exp: 'Event ID 4625 = failed logon attempt. 4624 = successful logon. 4740 = account locked out. 4720 = account created. Multiple 4625 events in quick succession indicate a brute-force attack. Monitor in Security event log.', domain: 'D1' },
  { q: 'Which Active Directory object is used to apply security policies to multiple users and computers based on their location in the directory?', opts: ['User account', 'Distribution group', 'Organizational Unit (OU)', 'Security identifier (SID)'], answer: 2, exp: 'Organizational Units (OUs) are containers that hold users, groups, and computers. Group Policy Objects (GPOs) can be linked to OUs to apply settings to all objects within the OU.', domain: 'D4' },
  { q: 'An Android user wants to install an app that is not on the Google Play Store. What setting must be enabled, and what is the security risk?', opts: ['Developer Mode; voids the warranty', 'Install from Unknown Sources / sideloading; risk of malicious APKs', 'Safe Mode; reduces functionality', 'Airplane Mode; disables verification'], answer: 1, exp: 'Sideloading APKs requires enabling install from unknown sources, which bypasses Google Play Protect scanning. Apps from unverified sources can contain malware, spyware, or banking trojans.', domain: 'D1' },
  { q: 'Which command-line tool on Linux shows currently running processes?', opts: ['ls', 'ps', 'pwd', 'cd'], answer: 1, exp: 'The ps command lists running processes. Common variants include ps aux for all users and ps -ef for full format. The top command provides a live, updating view of processes and resource usage.', domain: 'D1' },
  { q: 'Which type of Windows user account has the FEWEST privileges by default?', opts: ['Administrator', 'Standard user', 'Guest', 'Power User'], answer: 2, exp: 'The Guest account has the most limited rights — it cannot install software or change system settings, and its profile is wiped at logoff. Standard users can run apps and change personal settings but not system-wide settings.', domain: 'D1' },
  { q: 'A user calls the help desk and is extremely upset that their computer is not working. What is the BEST way for a technician to respond?', opts: ['Tell the user to calm down before you can help', 'Listen actively, acknowledge the issue, and avoid arguing or interrupting', 'Transfer the call to a manager immediately', 'Promise to fix it within the hour regardless of complexity'], answer: 1, exp: 'A+ professionalism objectives emphasize active listening, acknowledging frustration, avoiding interruption, and avoiding judgmental responses. Do not tell upset customers to calm down — it usually escalates the conflict.', domain: 'D1' },
  { q: 'Which PowerShell command lists all running services on a Windows machine?', opts: ['ls services', 'Get-Service', 'show-services', 'services.msc'], answer: 1, exp: 'Get-Service is the PowerShell cmdlet for listing Windows services. services.msc is the GUI Microsoft Management Console snap-in. The two are not interchangeable in scripts.', domain: 'D1' },
  { q: 'A Windows laptop will not boot and stops at a "BOOTMGR is missing" message. Which Windows Recovery Environment command should be run FIRST?', opts: ['sfc /scannow', 'bootrec /fixboot and bootrec /rebuildbcd', 'chkdsk /r', 'DISM /RestoreHealth'], answer: 1, exp: 'BOOTMGR errors indicate a damaged boot configuration. bootrec /fixboot writes a new boot sector and bootrec /rebuildbcd rebuilds the Boot Configuration Data. These are the targeted repairs for this symptom.', domain: 'D1' },
  { q: 'Which Linux command changes the OWNER of a file?', opts: ['chmod', 'chown', 'chgrp', 'chroot'], answer: 1, exp: 'chown (change owner) changes the user that owns a file. chgrp changes the group. chmod changes permissions. chroot changes the apparent root directory for a process.', domain: 'D1' },
  { q: 'What type of cloud deployment dedicates infrastructure to a single organization while still being hosted by a third-party provider?', opts: ['Public cloud', 'Hosted private cloud', 'Hybrid cloud', 'Community cloud'], answer: 1, exp: 'A hosted (or virtual) private cloud uses a third-party provider but dedicates resources to one customer for isolation and compliance. A community cloud is shared among organizations with similar needs.', domain: 'D4' },
  { q: 'Which Group Policy section applies settings that affect a computer regardless of which user logs in?', opts: ['User Configuration', 'Computer Configuration', 'Administrative Templates only', 'Local Security Policy only'], answer: 1, exp: 'Computer Configuration policies apply at boot and affect the machine regardless of who logs in. User Configuration policies apply at logon and follow the user account. Both branches exist in every GPO.', domain: 'D4' },
  { q: 'A technician is asked to dispose of several old hard drives containing company data. Which method ensures data CANNOT be recovered?', opts: ['Move files to the Recycle Bin and empty it', 'Quick format the drives', 'Physically shred or degauss the drives', 'Delete each file individually'], answer: 2, exp: 'Physical destruction (shredding) or degaussing (for magnetic media) ensures data cannot be recovered. Quick formats and deletes leave most data intact and recoverable with forensic tools.', domain: 'D1' },
  { q: 'A workstation displays the error "Inaccessible Boot Device" after a recent storage controller driver update. What is the BEST first step?', opts: ['Reinstall Windows from scratch', 'Boot to recovery and roll back the most recent driver or use System Restore', 'Replace the boot drive', 'Run memtest86'], answer: 1, exp: 'The error appeared right after a driver change, so the fastest fix is to undo the change. Boot to WinRE and roll back the driver or use System Restore to a point before the update.', domain: 'D3' },
  { q: 'Which Windows tool monitors real-time performance counters for CPU, memory, disk, and network with logging support?', opts: ['Task Manager', 'Resource Monitor', 'Performance Monitor (perfmon)', 'Event Viewer'], answer: 2, exp: 'Performance Monitor (perfmon.msc) provides extensive counter logging and data collector sets for long-term performance analysis. Resource Monitor offers a real-time view but limited historical logging.', domain: 'D1' },
  { q: 'A user wants to use biometrics to log into Windows 10. Which built-in feature should be enabled?', opts: ['BitLocker', 'Windows Hello', 'Credential Guard', 'Secure Boot'], answer: 1, exp: 'Windows Hello supports fingerprint, facial recognition (with compatible camera), and PIN sign-in. BitLocker is drive encryption. Credential Guard isolates credentials in a virtualized container.', domain: 'D1' },
  { q: 'Which file system is BEST for an external USB drive that needs to be read and written by both Windows and macOS without third-party drivers?', opts: ['NTFS', 'HFS+', 'exFAT', 'ext4'], answer: 2, exp: 'exFAT is supported natively by both Windows and macOS for read and write. NTFS is read-only on macOS without third-party drivers. HFS+ and ext4 are not natively supported on Windows.', domain: 'D1' },
  { q: 'A Mac user reports that an application is unresponsive. Which macOS feature force-quits a frozen app?', opts: ['Command + Q', 'Command + Option + Esc', 'Control + Alt + Delete', 'Mission Control'], answer: 1, exp: 'Command + Option + Esc opens the Force Quit Applications window on macOS, the equivalent of Task Manager End Task on Windows. Command + Q gracefully quits, which a frozen app will ignore.', domain: 'D1' },
  { q: 'A technician is documenting a change to a production server. Which document should the change be recorded in?', opts: ['Incident ticket', 'Change management record / change log', 'User manual', 'License inventory'], answer: 1, exp: 'Change management records (often a ticket in a CAB-approved workflow) capture the requested change, justification, rollback plan, approver, and outcome. This provides auditability and helps troubleshoot future issues.', domain: 'D4' },
  { q: 'Which type of malware demands payment, often in cryptocurrency, to restore access to encrypted files?', opts: ['Spyware', 'Adware', 'Ransomware', 'Keylogger'], answer: 2, exp: 'Ransomware encrypts user files and demands payment for the decryption key. Examples include WannaCry, Ryuk, and LockBit. The best defense is offline, tested backups and timely patching.', domain: 'D2' },
  { q: 'Which Windows command-line utility is used to map a network drive from a script?', opts: ['ipconfig', 'net use', 'netstat', 'nbtstat'], answer: 1, exp: 'net use Z: \\\\\\\\server\\\\share maps a network drive in scripts and batch files. New-PSDrive is the PowerShell equivalent. Manual mapping can also be done from File Explorer.', domain: 'D1' },
  { q: 'Which mobile security feature uses two distinct verification methods, such as a password and a code sent to the user phone?', opts: ['Encryption at rest', 'Multifactor authentication (MFA)', 'Remote wipe', 'Containerization'], answer: 1, exp: 'MFA requires two or more verification factors from different categories. A password (something you know) plus an SMS or authenticator code (something you have) is the most common implementation.', domain: 'D2' },
  { q: 'A technician must wear which item to safely work inside an open desktop chassis to prevent ESD damage?', opts: ['Latex gloves', 'Anti-static wrist strap connected to the chassis', 'Safety goggles', 'Rubber-soled shoes'], answer: 1, exp: 'An anti-static (ESD) wrist strap drains static charge from the technician body to the chassis, preventing electrostatic discharge from damaging sensitive components. Anti-static mats serve a similar purpose for workspaces.', domain: 'D4' },
  { q: 'Which Windows feature isolates a downloaded executable in a virtualized environment to safely test it?', opts: ['BitLocker', 'Windows Sandbox', 'System Restore', 'Storage Spaces'], answer: 1, exp: 'Windows Sandbox (available in Pro and Enterprise) provides a lightweight, disposable virtual environment. The sandbox state resets on close, leaving no residue from anything tested inside it.', domain: 'D1' },
  { q: 'A user reports that their Windows 11 laptop is significantly slower after the most recent feature update. Other troubleshooting has been unproductive. Which built-in feature lets the user roll back to the previous Windows version within 10 days?', opts: ['System Restore', 'Reset this PC', 'Go back to the previous version of Windows (Recovery menu)', 'Refresh image'], answer: 2, exp: 'Within 10 days of a feature update, Windows 11 keeps the previous build in Windows.old and exposes a Go back option under Settings > System > Recovery. After 10 days the files are removed and the option is no longer available.', domain: 'D3' },
  { q: 'A technician needs to install Windows 11 on a workstation that has a 3 TB drive intended as the boot device. Which partitioning scheme is REQUIRED?', opts: ['MBR with legacy BIOS', 'GPT with UEFI', 'FAT32 with legacy BIOS', 'exFAT with UEFI'], answer: 1, exp: 'MBR is limited to 2 TB partitions. Drives larger than 2 TB used as a boot disk require GPT, and GPT booting on Windows requires UEFI firmware. Windows 11 itself also mandates UEFI with Secure Boot.', domain: 'D1' },
  { q: 'A user reports that their macOS Mac is running low on disk space, and the technician wants to find which applications and files are largest. Which built-in macOS feature provides this view?', opts: ['Disk Utility First Aid', 'System Settings > General > Storage (Manage Storage)', 'Mission Control', 'Time Machine restore'], answer: 1, exp: 'macOS Manage Storage shows usage by category (Applications, Documents, Mail, etc.) and lets the user remove large files. Disk Utility First Aid repairs disk errors. Time Machine handles backups, not storage analysis.', domain: 'D1' },
  { q: 'Which file system is the appropriate default for a Windows 10 / 11 internal system drive?', opts: ['FAT32', 'exFAT', 'NTFS', 'HFS+'], answer: 2, exp: 'NTFS is required for the Windows boot volume and supports permissions, EFS, large files, and journaling. FAT32 has a 4 GB file size limit, exFAT lacks permissions and journaling, and HFS+ is an Apple file system.', domain: 'D1' },
  { q: 'A technician wants to give a user the ability to install applications and change system settings on their own Windows workstation. Which user account type provides this?', opts: ['Standard user', 'Guest', 'Administrator', 'Power User'], answer: 2, exp: 'Administrators can install software, change system settings, and manage other accounts. Standard users cannot install most software system-wide without elevation. Guest is highly restricted. Power User is largely deprecated in modern Windows.', domain: 'D1' },
  { q: 'A technician must securely erase an SSD before donating the workstation. Which method is the MOST appropriate?', opts: ['Quick format the drive', 'Use the manufacturer\'s Secure Erase utility (ATA Secure Erase) or full-disk encryption followed by key destruction', 'Drag files to the Recycle Bin and empty', 'Defragment the drive'], answer: 1, exp: 'ATA Secure Erase is implemented in the SSD controller and resets all cells to factory state. Multi-pass overwrites are unreliable on SSDs due to wear leveling. Quick format and Recycle Bin leave most data recoverable.', domain: 'D1' },
  { q: 'A user reports that an application installed yesterday is now causing Windows to blue-screen on every boot. Which Windows Recovery Environment option will MOST efficiently resolve the issue?', opts: ['Reset this PC (remove everything)', 'Boot to Safe Mode and uninstall the application, or use System Restore to a point before the install', 'Reinstall Windows from USB media', 'Replace the storage drive'], answer: 1, exp: 'Safe Mode loads only essential drivers, allowing uninstall of the offending app. System Restore reverts system files and registry without affecting user data. Full reset or reinstall is a heavy-handed step when a targeted fix is available.', domain: 'D1' },
  { q: 'A technician needs to image multiple identical workstations quickly. Which TWO Windows technologies BEST support this workflow?', opts: ['Notepad and WordPad', 'Sysprep with Windows Imaging Format (WIM) files captured by DISM', 'Cortana voice setup', 'Personal OneDrive sync'], answer: 1, exp: 'Sysprep generalizes a reference image so it can be deployed to multiple hardware sets. DISM captures and applies WIM images. Together they form the core Windows deployment workflow used by MDT and ConfigMgr.', domain: 'D1' },
  { q: 'Which Linux command lists the contents of the current directory in long format with file permissions, owner, and size?', opts: ['cd', 'pwd', 'ls -l', 'mv'], answer: 2, exp: 'ls -l shows a long listing including type, permission bits, owner, group, size, and modification time. pwd prints the working directory, cd changes directory, and mv moves or renames files.', domain: 'D1' },
  { q: 'A technician needs to provide a junior tech with read-only access to view server logs without granting any modification rights. Which principle BEST guides this assignment?', opts: ['Implicit allow', 'Least privilege', 'Separation of duties', 'Defense in depth'], answer: 1, exp: 'Least privilege grants only the access needed to perform the job, and nothing more. Read-only access to logs lets the junior tech monitor without risking accidental changes. The other concepts are useful but do not describe this specific granting decision.', domain: 'D1' },
  { q: 'A user installed a new app from outside the Apple App Store on macOS and the system refuses to open it, citing an unidentified developer. Which is the appropriate FIRST action?', opts: ['Disable System Integrity Protection completely', 'Open System Settings > Privacy & Security and review the gatekeeper warning, allowing the app only if it is trusted', 'Reinstall macOS', 'Disable the firewall'], answer: 1, exp: 'macOS Gatekeeper blocks unsigned apps by default. The Privacy & Security pane shows a one-click override if the user trusts the source. Disabling SIP or the firewall is far more invasive than this issue requires.', domain: 'D1' },
  { q: 'A user reports that pop-up advertisements appear on their Windows PC even when no browser is open. Which malware category is the MOST likely cause?', opts: ['Rootkit', 'Adware (potentially unwanted program)', 'Hardware failure', 'Driver mismatch'], answer: 1, exp: 'Persistent pop-ups outside a browser, often bundled with free downloads, are classic adware. Treatment includes removing the unwanted program from Apps & Features and running a reputable anti-malware scanner.', domain: 'D2' },
  { q: 'A small business wants centralized authentication so that users log in once with a single account that grants access to file shares, email, and intranet apps. Which technology BEST provides this in a Windows environment?', opts: ['Local user accounts on each PC', 'Active Directory Domain Services with Kerberos / NTLM and SSO', 'Workgroup with shared passwords', 'Manual login per service'], answer: 1, exp: 'Active Directory Domain Services provides centralized account management and single sign-on across domain-joined resources using Kerberos. Workgroups and local accounts do not scale and lack centralized policy enforcement.', domain: 'D1' },
  { q: 'A technician must transport sensitive corporate data on a removable drive between two offices. Which control BEST protects the data if the drive is lost in transit?', opts: ['Label the drive with the office address', 'Encrypt the drive (for example, BitLocker To Go) with a strong password', 'Use a smaller-capacity drive', 'Wrap the drive in tape'], answer: 1, exp: 'Full-drive encryption renders the data unreadable without the key, even if the drive is physically lost. Labels actually increase risk by identifying the owner. Wrapping the drive does nothing for data confidentiality.', domain: 'D2' },
  { q: 'Which port does SMTP use to transfer outbound email between mail servers?', opts: ['25', '110', '143', '443'], answer: 0, exp: 'SMTP (Simple Mail Transfer Protocol) uses port 25 for server-to-server mail transfer. POP3 uses 110, IMAP uses 143, and HTTPS uses 443. Client mail submission often uses port 587.', domain: 'D2' },
  { q: 'According to the CompTIA troubleshooting methodology, which step comes IMMEDIATELY after establishing a theory of probable cause?', opts: ['Document the findings', 'Test the theory to determine the cause', 'Establish a plan of action', 'Identify the problem'], answer: 1, exp: 'The order is: identify the problem; establish a theory; test the theory to determine cause; establish a plan of action and implement it; verify full functionality; document findings. Testing the theory directly follows establishing it.', domain: 'D1' },
  { q: 'A technician has resolved an issue and verified full system functionality. What is the FINAL step of the troubleshooting process?', opts: ['Escalate the ticket', 'Document the findings, actions, and outcomes', 'Establish a new theory', 'Reboot the system'], answer: 1, exp: 'The final step is documenting findings, actions, and outcomes. Good documentation builds a knowledge base, speeds future troubleshooting, and provides an audit trail. Skipping it wastes the lessons learned.', domain: 'D4' },
  { q: 'Print jobs are stuck in the queue on a Windows PC and will not clear or print. Which service should the technician restart?', opts: ['Workstation service', 'Print Spooler service', 'Windows Update service', 'DHCP Client service'], answer: 1, exp: 'The Print Spooler manages queued print jobs. Restarting it (services.msc, or net stop spooler / net start spooler) clears a hung queue. If a job is corrupt, files in the spool folder may also need to be deleted.', domain: 'D1' },
  { q: 'A technician needs to extend the C: volume into adjacent unallocated space on a Windows workstation. Which built-in tool should be used?', opts: ['Device Manager', 'Disk Management', 'Task Manager', 'Event Viewer'], answer: 1, exp: 'Disk Management (diskmgmt.msc) creates, formats, extends, and shrinks volumes. Extend Volume works only into unallocated space immediately to the right of the partition. diskpart is the command-line equivalent.', domain: 'D1' },
  { q: 'A USB device fails and the technician suspects a driver problem. Where in Windows is a device with a driver issue shown with a yellow exclamation mark?', opts: ['Disk Management', 'Device Manager', 'Programs and Features', 'System Information'], answer: 1, exp: 'Device Manager lists all hardware; a yellow exclamation mark indicates a driver or configuration problem and a down arrow indicates a disabled device. From there a technician can update, roll back, or reinstall the driver.', domain: 'D3' },
  { q: 'A small business needs to join PCs to a domain and use Group Policy and BitLocker. Which is the MINIMUM Windows 10/11 edition required?', opts: ['Windows Home', 'Windows Pro', 'Windows in S mode', 'Windows IoT Core'], answer: 1, exp: 'Windows Home cannot join a domain and lacks BitLocker, the Group Policy Editor, and Remote Desktop hosting. Windows Pro (or Enterprise/Education) is the minimum edition for these business features.', domain: 'D4' },
  { q: 'A standard user attempts to install software and is prompted to enter administrator credentials. Which Windows security feature triggered this prompt?', opts: ['Windows Defender Firewall', 'User Account Control (UAC)', 'BitLocker', 'Secure Boot'], answer: 1, exp: 'UAC prompts for elevation when an action needs administrative rights, preventing silent privileged changes by users or malware. Standard users must supply admin credentials; administrators simply approve the prompt.', domain: 'D1' },
  { q: 'An attacker sends a highly personalized fraudulent email to a company CFO, referencing a genuine vendor relationship to request a wire transfer. Which attack is this?', opts: ['Whaling', 'Shoulder surfing', 'Tailgating', 'Dumpster diving'], answer: 0, exp: 'Whaling is spear phishing aimed at high-value executives (the "big fish"). Personalization and references to real relationships make it convincing. Always verify financial requests through a separate, trusted channel.', domain: 'D2' },
  { q: 'An unauthorized individual closely follows an employee through a badge-secured door without scanning a credential. What is this physical security attack called?', opts: ['Phishing', 'Tailgating', 'On-path attack', 'Spoofing'], answer: 1, exp: 'Tailgating (piggybacking) is following an authorized person through a secure door. Access control vestibules (mantraps) and security-awareness training are effective countermeasures.', domain: 'D2' },
  { q: 'Which control BEST prevents shoulder surfing of confidential data on a laptop used in public spaces?', opts: ['A stronger password', 'A privacy screen filter', 'Full-disk encryption', 'A cable lock'], answer: 1, exp: 'A privacy screen filter narrows the viewing angle so only the person directly in front can read the display. Encryption protects data at rest and a cable lock deters theft — neither stops visual eavesdropping.', domain: 'D2' },
  { q: 'Workstations in a building repeatedly reboot during short periods of reduced line voltage. What power condition is occurring?', opts: ['Power surge', 'Brownout (sag)', 'Blackout', 'Electrostatic discharge'], answer: 1, exp: 'A brownout is a sustained drop in voltage (a sag is a brief one) that causes unstable operation and reboots. A blackout is total loss of power. A UPS rides through brownouts and protects equipment.', domain: 'D1' },
  { q: 'Which file extension identifies a Windows PowerShell script?', opts: ['.bat', '.ps1', '.vbs', '.sh'], answer: 1, exp: 'PowerShell scripts use the .ps1 extension. .bat is a legacy batch file, .vbs is a VBScript file, and .sh is a Unix/Linux shell script. Recognizing script types is part of A+ Core 2 scripting objectives.', domain: 'D1' },
  { q: 'A technician needs to write an automation script that will run on a Linux server. Which file type is appropriate?', opts: ['.ps1', '.bat', '.sh', '.vbs'], answer: 2, exp: 'A .sh shell script is the standard scripting format on Linux and Unix systems. .ps1 (PowerShell) and .bat (batch) are Windows-oriented, and .vbs is Windows VBScript.', domain: 'D1' },
  { q: 'A customer database stores names, home addresses, and Social Security numbers. How should this information be classified?', opts: ['Public data', 'Personally Identifiable Information (PII)', 'Telemetry data', 'Ephemeral data'], answer: 1, exp: 'PII is any data that can identify a specific individual, such as a name combined with an SSN or address. It must be protected per privacy regulations; mishandling can lead to identity theft and legal penalties.', domain: 'D2' },
  { q: 'Patient medical records handled by a U.S. healthcare provider are governed primarily by which regulation?', opts: ['PCI DSS', 'HIPAA', 'GDPR', 'SOX'], answer: 1, exp: 'HIPAA governs the privacy and security of protected health information (PHI) in the United States. PCI DSS covers payment-card data, GDPR covers EU personal data, and SOX covers corporate financial reporting.', domain: 'D4' },
  { q: 'A user logs in with a password and then enters a one-time code from a smartphone authenticator app. Which authentication design is in use?', opts: ['Single-factor authentication', 'Multifactor authentication (something you know + something you have)', 'Multifactor authentication (something you know + something you are)', 'Single sign-on (SSO)'], answer: 1, exp: 'A password is "something you know" and a TOTP code from a phone authenticator app is "something you have." Two different factor types = MFA. A second password would still be single-factor; biometric would make it know + are.', domain: 'D2' },
  { q: 'A login system asks users to type their password and answer a security question. Why is this NOT true multifactor authentication?', opts: ['Security questions are always encrypted', 'Both factors fall in the "something you know" category', 'The session times out too quickly', 'Security questions are not allowed by NIST'], answer: 1, exp: 'MFA requires factors from DIFFERENT categories (know / have / are). A password and a security question are both "something you know," so the combination is still single-factor — easier to phish or guess than true MFA.', domain: 'D2' },
  { q: 'Which authentication factor is generally the MOST phishing-resistant when properly implemented?', opts: ['SMS one-time code', 'A long memorized password', 'TOTP authenticator app', 'FIDO2 hardware security key'], answer: 3, exp: 'FIDO2 / WebAuthn hardware keys (YubiKey, Titan, Feitian) bind the cryptographic challenge to the actual site origin, so a phishing page cannot relay it. TOTP can still be entered on a fake site; SMS is also vulnerable to SIM swapping.', domain: 'D2' },
  { q: 'A standard user can read files in a shared folder but cannot delete or rename any. Which security principle BEST describes this configuration?', opts: ['Defense in depth', 'Principle of least privilege', 'Separation of duties', 'Zero trust'], answer: 1, exp: 'Least privilege grants users only the minimum permissions needed to do their job. Read-only access where write or delete is not required is the textbook example. Separation of duties involves splitting one task across multiple people.', domain: 'D1' },
  { q: 'In an enterprise environment, which authentication model assigns permissions based on a user’s job title (e.g., "Accountant," "HR Manager")?', opts: ['DAC (Discretionary Access Control)', 'MAC (Mandatory Access Control)', 'RBAC (Role-Based Access Control)', 'Federation'], answer: 2, exp: 'RBAC assigns permissions to roles, then assigns users to roles. Adding or revoking access is done by changing role membership. DAC lets the owner set permissions; MAC uses fixed labels (Top Secret, etc.); federation links identity across orgs.', domain: 'D1' },
  { q: 'A small office wants the strongest currently available wireless protection. Which configuration should the technician choose?', opts: ['WEP with a 128-bit key', 'WPA-TKIP', 'WPA2-Personal (AES-CCMP)', 'WPA3-Personal (SAE)'], answer: 3, exp: 'WPA3-Personal uses SAE (Simultaneous Authentication of Equals), which resists offline dictionary attacks on the PSK and enforces PMF. WPA2-AES is an acceptable fallback for legacy devices; WEP and WPA-TKIP are broken.', domain: 'D1' },
  { q: 'A coffee shop offers free Wi-Fi that opens a web page requiring email and acceptance of terms before granting Internet access. What is this called?', opts: ['802.1X authentication', 'A captive portal', 'WPA3-Enterprise', 'A reverse proxy'], answer: 1, exp: 'A captive portal intercepts traffic and forces login or T&Cs acceptance before granting access. It does not encrypt the wireless link by itself — the over-the-air traffic may still be open if no WPA is configured.', domain: 'D2' },
  { q: 'A company is concerned about employees being followed into a secure data center by unauthorized individuals. Which physical control BEST addresses this?', opts: ['Cable locks on the equipment', 'An access control vestibule (mantrap)', 'CCTV recording the door', 'A clean desk policy'], answer: 1, exp: 'An access control vestibule (mantrap) has two interlocking doors — only one opens at a time, defeating tailgating / piggybacking. CCTV records the event but does not prevent entry. Cable locks protect equipment, not access.', domain: 'D4' },
  { q: 'Which control is an example of a PHYSICAL security control rather than a logical / technical one?', opts: ['A host-based firewall', 'A privacy screen filter at a teller window', 'BitLocker full-disk encryption', 'Multifactor authentication on email'], answer: 1, exp: 'Physical controls are tangible: locks, badges, mantraps, privacy filters, fences, lighting, cable locks. Firewalls, encryption, and MFA are logical / technical controls. CompTIA tests the physical vs technical vs administrative classification often.', domain: 'D2' },
  { q: 'A laptop is used in a busy public area. Which control BEST prevents shoulder surfing of confidential data on screen?', opts: ['Full-disk encryption', 'A privacy screen filter', 'A stronger Windows password', 'Disabling AutoPlay for removable media'], answer: 1, exp: 'A privacy screen filter narrows the viewing angle so only the person directly in front can read the display. Encryption protects data at rest but not what is visible. Passwords and AutoPlay address different threats entirely.', domain: 'D2' },
  { q: 'Which password policy recommendation is supported by current NIST guidance (SP 800-63B)?', opts: ['Force users to rotate passwords every 30 days', 'Require all four character classes regardless of length', 'Favor length (12+ characters) and only force a change after a known compromise', 'Permit users to share strong passwords across accounts'], answer: 2, exp: 'Modern NIST guidance prioritizes length over complexity, removes mandatory rotation, and recommends checking against known-breached password lists. MFA is more impactful than rotation. Sharing or reusing passwords is never acceptable.', domain: 'D2' },
  { q: 'A technician needs to defend against online brute-force attacks against user accounts. Which control is MOST effective?', opts: ['Disable USB ports on every workstation', 'Configure account lockout after a small number of failed attempts', 'Increase the screensaver timeout', 'Disable the system tray'], answer: 1, exp: 'Account lockout (for example, lock for 30 minutes after 5 failed attempts) directly stops online brute-force by removing the attacker’s ability to keep guessing. Combine with MFA and strong passwords for layered defense.', domain: 'D2' },
  { q: 'A help-desk technician needs to handle routine tickets and also do occasional system administration. Which is the BEST account practice?', opts: ['Use the Domain Administrator account for everything', 'Use a single account with Local Administrator rights for all tasks', 'Use a Standard user account for daily work and a separate Admin account only for administrative tasks', 'Disable User Account Control (UAC) so the technician is never prompted'], answer: 2, exp: 'Separating standard-user activity from administrative actions limits the blast radius of malware or a phishing click during normal browsing or email. UAC should be left enabled — it catches unwanted privilege escalation.', domain: 'D2' },
  { q: 'Why should AutoPlay / AutoRun be disabled for removable media on Windows endpoints?', opts: ['It improves disk performance', 'It prevents an unknown USB drive from silently launching code (USB drop attacks)', 'It is required for BitLocker encryption', 'It is required for Secure Boot'], answer: 1, exp: 'AutoRun used to launch executables automatically when removable media was inserted, which attackers exploited with USB drop attacks (leaving malicious USBs in parking lots). Disabling AutoPlay forces the user to explicitly open files.', domain: 'D1' },
  { q: 'A bank is retiring SSDs that contained customer financial records. Which destruction method is MOST appropriate?', opts: ['A multi-pass DoD 5220.22-M software wipe', 'A standard quick format', 'Crypto Erase (destroying the on-drive encryption key) or physical shredding', 'Degaussing with a hard-drive degausser'], answer: 2, exp: 'SSDs use wear-leveling, so software overwrites are unreliable. Crypto Erase destroys the on-drive encryption key, making existing data instantly unreadable. Physical shredding to particle size is also acceptable. Degaussing has no effect on flash storage.', domain: 'D1' },
  { q: 'A technician needs to securely sanitize hundreds of decommissioned magnetic hard drives. Which method is acceptable?', opts: ['Degaussing with a properly rated degausser', 'Reformatting with the OS installer', 'Deleting the partition table only', 'Storing the drives in a locked closet'], answer: 0, exp: 'Degaussing applies a strong magnetic field that scrambles platters on magnetic media (HDDs and tape), rendering them unusable. Software methods (NIST 800-88 Clear, DoD 5220.22-M) are also acceptable for HDDs. Storage or partition deletion is NOT secure disposal.', domain: 'D1' },
  { q: 'Why is a Quick Format NOT considered secure data destruction?', opts: ['It corrupts the disk so it can no longer be used', 'It only rewrites the file allocation table; data blocks remain recoverable until overwritten', 'It triggers Secure Boot warnings', 'It removes the master boot record'], answer: 1, exp: 'Quick Format clears the index that tells the OS where files live, but the underlying data blocks remain on the platters or cells until something writes over them. Recovery tools (Recuva, commercial forensics) can readily restore files after a Quick Format.', domain: 'D1' },
  { q: 'A workstation displays a ransom note demanding cryptocurrency to decrypt the user’s files. According to the CompTIA malware-removal procedure, what is the FIRST action the technician should take?', opts: ['Pay the ransom from a corporate account', 'Boot the computer to Safe Mode and run an AV scan', 'Disconnect the workstation from the network to contain the infection', 'Restore from the latest backup immediately'], answer: 2, exp: 'CompTIA’s 7-step malware removal puts Quarantine FIRST — disconnect the network cable or Wi-Fi to prevent the ransomware from spreading to file shares or talking to its command-and-control server. Only AFTER containment do you boot to Safe Mode, run scanners, remediate, and restore.', domain: 'D2' },
];
